<script setup>
import { computed, ref } from 'vue'
import { useEvents } from '@/composables/useEvents'
import EventCard from '@/components/event/EventCard.vue'
const { activeEvents, isUserRegistered } = useEvents()
const query=ref(''),selectedCategory=ref('All events')
const categories=computed(()=>['All events',...new Set(activeEvents.value.map(e=>e.category).filter(Boolean))])
const filteredEvents=computed(()=>{const term=query.value.trim().toLowerCase();return activeEvents.value.filter(e=>(selectedCategory.value==='All events'||e.category===selectedCategory.value)&&(!term||[e.title,e.location,e.category,e.desc].some(v=>String(v||'').toLowerCase().includes(term))))})
</script>
<template>
<div class="event-list-page"><header class="catalog-heading"><div><span class="eyebrow">FIND YOUR NEXT MOMENT</span><h2>Upcoming Events</h2><p>Discover gatherings, ideas, and experiences happening around you.</p></div><RouterLink to="/dashboard/events" class="organizer-link">Host an event ↗</RouterLink></header><section class="catalog-tools" aria-label="Search and filter events"><label class="search-field"><span aria-hidden="true">⌕</span><input v-model="query" type="search" placeholder="Search events, places, or topics" aria-label="Search events"></label><div class="category-filters"><button v-for="category in categories" :key="category" type="button" :class="{selected:selectedCategory===category}" @click="selectedCategory=category">{{category}}</button></div></section><div v-if="filteredEvents.length" class="event-grid"><EventCard v-for="event in filteredEvents" :key="event.id" :event="event" :is-registered="isUserRegistered(event.id)" /></div><section v-else class="empty-state"><div class="empty-illustration">◈</div><span class="eyebrow">{{activeEvents.length?'NO MATCHES FOUND':'A FRESH START'}}</span><h3>{{activeEvents.length?'No events match your search':'Your next great event is waiting'}}</h3><p>{{activeEvents.length?'Try another search term or choose a different category.':'There are no upcoming events just yet. Check back soon or start something new.'}}</p><button v-if="activeEvents.length" type="button" class="reset-button" @click="query='';selectedCategory='All events'">Clear filters</button><RouterLink v-else to="/dashboard/events" class="organizer-link">Create the first event →</RouterLink></section></div>
</template>
